CREATE DATABASE IF NOT EXISTS tramite_documentario CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tramite_documentario;
CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE areas (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(120) NOT NULL UNIQUE, descripcion VARCHAR(255));
CREATE TABLE usuarios (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombres VARCHAR(120) NOT NULL, correo VARCHAR(120) NOT NULL UNIQUE, clave VARCHAR(255), activo BOOLEAN DEFAULT TRUE, rol_id BIGINT, area_id BIGINT, FOREIGN KEY(rol_id) REFERENCES roles(id), FOREIGN KEY(area_id) REFERENCES areas(id));
CREATE TABLE documentos (id BIGINT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(30) NOT NULL UNIQUE, tipo_documento VARCHAR(80) NOT NULL, remitente VARCHAR(150) NOT NULL, dni_ruc VARCHAR(15) NOT NULL, asunto VARCHAR(255) NOT NULL, fecha_recepcion DATE, descripcion VARCHAR(1000), estado VARCHAR(30), area_destino_id BIGINT, FOREIGN KEY(area_destino_id) REFERENCES areas(id));
CREATE TABLE tramites (id BIGINT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(30) NOT NULL UNIQUE, tipo_tramite VARCHAR(80) NOT NULL, solicitante VARCHAR(150) NOT NULL, dni_ruc VARCHAR(15) NOT NULL, asunto VARCHAR(255) NOT NULL, descripcion VARCHAR(1000), fecha_registro DATE, estado VARCHAR(30), area_responsable_id BIGINT, FOREIGN KEY(area_responsable_id) REFERENCES areas(id));
CREATE TABLE historial_tramites (id BIGINT AUTO_INCREMENT PRIMARY KEY, tramite_id BIGINT NOT NULL, estado VARCHAR(30), fecha DATETIME, responsable VARCHAR(120), observacion VARCHAR(500), area_id BIGINT, FOREIGN KEY(tramite_id) REFERENCES tramites(id), FOREIGN KEY(area_id) REFERENCES areas(id));
CREATE TABLE derivaciones (id BIGINT AUTO_INCREMENT PRIMARY KEY, tramite_id BIGINT NOT NULL, area_destino_id BIGINT NOT NULL, responsable VARCHAR(120), observacion VARCHAR(500), fecha DATETIME, FOREIGN KEY(tramite_id) REFERENCES tramites(id), FOREIGN KEY(area_destino_id) REFERENCES areas(id));
